using UnityEngine;

namespace LaserHero
{
    // Shapes are regenerated by the existing destruction system when a round starts.
    public static class LaserOceanShapes
    {
        static bool Branch(Vector3 p, Vector3 a, Vector3 b, float radius)
        {
            Vector3 ab = b - a;
            float t = Mathf.Clamp01(Vector3.Dot(p - a, ab) / Mathf.Max(.001f, ab.sqrMagnitude));
            return (p - a - ab * t).sqrMagnitude <= radius * radius;
        }

        public static bool Cell(int style, int x, int y, int z, Vector3Int d, float cell, Vector3 origin, out byte colour)
        {
            colour = 0;
            float cx = (d.x - 1) * .5f, cz = (d.z - 1) * .5f;
            float u = (x - cx) / Mathf.Max(1, cx), w = (z - cz) / Mathf.Max(1, cz), v = y / (float)Mathf.Max(1, d.y - 1);
            float r = Mathf.Sqrt(u * u + w * w);
            Vector3 p = new Vector3(x - cx, y, z - cz);
            if (style == 50) // Deep, fully solid sand over sediment and ocean bedrock.
            {
                colour = (byte)(y < 6 ? 2 : y < d.y - 5 ? 1 : 0);
                if (y == d.y - 1)
                {
                    float wx = origin.x + (x + .5f) * cell, wz = origin.z + (z + .5f) * cell;
                    if (Mathf.Abs(wx) < 4.5f && wz < 145)
                        colour = 4;
                    else if (Mathf.Sin(wx * .19f + Mathf.Sin(wz * .16f)) > .86f)
                        colour = 3;
                }

                return true;
            }

            if (style == 51) // Thick connected branches: deliberately tall and easy to topple.
            {
                float h = d.y - 2, thickness = Mathf.Max(1.25f, d.x * .09f * (1 - v * .35f));
                colour = (byte)(v > .74f ? 1 : v < .12f ? 2 : 0);
                return Branch(p, Vector3.zero, new Vector3(0, h, 0), thickness)
                    || Branch(p, new Vector3(0, h * .28f, 0), new Vector3(-cx * .82f, h * .76f, 0), thickness)
                    || Branch(p, new Vector3(0, h * .48f, 0), new Vector3(cx * .82f, h * .9f, cz * .12f), thickness)
                    || Branch(p, new Vector3(0, h * .36f, 0), new Vector3(cx * .12f, h * .7f, -cz * .78f), thickness)
                    || Branch(p, new Vector3(0, h * .55f, 0), new Vector3(-cx * .15f, h * .94f, cz * .75f), thickness);
            }

            if (style == 52) // Three hollow tube sponges rooted in one low reef mound.
            {
                colour = (byte)(v > .83f ? 1 : v < .09f ? 2 : 0);
                if (y < 3 && r < .88f)
                    return true;
                for (int k = 0; k < 3; k++)
                {
                    float a = k * Mathf.PI * 2 / 3;
                    float dx = x - cx - Mathf.Cos(a) * cx * .46f, dz = z - cz - Mathf.Sin(a) * cz * .46f;
                    float outer = Mathf.Max(2, d.x * .18f) * (1 + .08f * Mathf.Sin(y * .3f));
                    float distance = dx * dx + dz * dz;
                    if (y < d.y * (1 - k * .15f) && distance <= outer * outer
                        && (distance >= (outer - 1.5f) * (outer - 1.5f) || y < 4))
                        return true;
                }

                return false;
            }

            if (style == 53) // Broad kelp fronds connect directly to the bending main stem.
            {
                float sx = Mathf.Sin(y * .13f) * cx * .33f;
                colour = (byte)(y % 14 < 4 ? 1 : 0);
                if ((x - cx - sx) * (x - cx - sx) + (z - cz) * (z - cz) < 1.8f)
                    return true;
                int node = y / 7 * 7;
                float side = (node / 7) % 2 == 0 ? 1 : -1;
                Vector3 a = new Vector3(Mathf.Sin(node * .13f) * cx * .33f, node, 0);
                return Branch(p, a, a + new Vector3(side * cx * .77f, 5, cz * .25f), 1.25f);
            }

            if (style == 54) // Weathered tapering underwater stone stacks.
            {
                float radius = .48f * (1 - v * .72f) + Mathf.Sin(v * 18) * .035f;
                colour = (byte)(y % 13 < 3 ? 1 : v > .8f ? 2 : 0);
                return r <= radius * 2;
            }

            if (style == 55) // Carved ancient columns, capitals and square footings.
            {
                colour = (byte)(y < 3 || y > d.y - 5 ? 1 : y % 14 == 0 ? 2 : 0);
                return y < 3 || y > d.y - 5 ? r < 1.02f : r < .58f;
            }

            if (style == 56) // A closed masonry arch with an intentional walk-through opening.
            {
                float outer = d.y * .44f + Mathf.Sqrt(Mathf.Max(0, 1 - u * u)) * d.y * .54f;
                float innerU = (x - cx) / Mathf.Max(1, cx - 4);
                float inner = d.y * .44f + Mathf.Sqrt(Mathf.Max(0, 1 - innerU * innerU)) * (d.y * .54f - 5);
                colour = (byte)(y % 9 < 2 ? 1 : z == 0 || z == d.z - 1 ? 2 : 0);
                return y <= outer && (Mathf.Abs(x - cx) >= cx - 4 || y >= inner);
            }

            if (style == 57) // Boat hull, connected keel, ribs and partially broken deck.
            {
                float width = Mathf.Max(1.5f, cx * Mathf.Pow(Mathf.Max(0, Mathf.Sin((z + .5f) / d.z * Mathf.PI)), .5f));
                float half = width * (.5f + .5f * Mathf.Clamp01(y / (d.y * .65f)));
                bool hull = y < d.y * .72f && Mathf.Abs(x - cx) <= half && (y < 2 || Mathf.Abs(x - cx) > half - 2);
                bool ribs = z % 6 < 2 && y < d.y * .72f && Mathf.Abs(x - cx) <= half;
                bool deck = y == (int)(d.y * .67f) && Mathf.Abs(x - cx) < half && (z < d.z * .55f || x < cx);
                colour = (byte)(y % 6 < 2 ? 1 : 0);
                return hull || ribs || deck;
            }

            if (style == 58) // Tall mast, two crossbars and connected ragged sails.
            {
                bool mast = Mathf.Abs(x - cx) < 1.4f && Mathf.Abs(z - cz) < 1.4f;
                bool bar = (Mathf.Abs(y - d.y * .8f) < 1.2f || Mathf.Abs(y - d.y * .55f) < 1.2f) && Mathf.Abs(z - cz) < 1.2f;
                float top = y > d.y * .61f ? d.y * .8f : d.y * .55f;
                bool sail = y < top && y > top - d.y * .18f && Mathf.Abs(z - cz) < .8f
                    && Mathf.Abs(u) < .88f && (y > top - d.y * .14f || x % 5 < 3);
                colour = (byte)(sail && !mast && !bar ? 2 : 0);
                return mast || bar || sail;
            }

            if (style == 59) // Banded treasure chest with a rounded top and golden clasp.
            {
                float top = d.y * .55f + Mathf.Sqrt(Mathf.Max(0, 1 - w * w)) * d.y * .44f;
                colour = (byte)(x < 2 || x >= d.x - 2 || y == (int)(d.y * .55f) ? 1 : Mathf.Abs(u) < .22f
                    && z == 0 && y > d.y * .25f ? 2 : 0);
                return y <= top;
            }

            if (style == 60) // Scalloped shell with radial colour ridges.
            {
                float angle = Mathf.Atan2(w, u);
                float rim = .88f + .1f * Mathf.Cos(angle * 9);
                colour = (byte)(Mathf.Cos(angle * 9) > .25f ? 1 : 0);
                return r < rim && y < 2 + (d.y - 2) * (1 - r);
            }

            if (style == 61) // Five-point starfish on the sand.
            {
                float angle = Mathf.Atan2(w, u);
                float edge = .6f + .3f * Mathf.Cos(angle * 5);
                colour = (byte)(y == d.y - 1 ? 1 : 0);
                return r < edge && y < d.y * (1 - r * .45f);
            }

            if (style == 62) // Lost cargo barrels.
            {
                colour = (byte)(y == 1 || y == d.y - 2 ? 1 : 0);
                return r < .83f;
            }

            if (style == 63) // Exploration submarine: pressure hull, tower, windows and fins.
            {
                float centerY = d.y * .39f, radius = d.y * .34f;
                float axial = Mathf.Sin((z + .5f) / d.z * Mathf.PI);
                float taper = .3f + .7f * Mathf.Sqrt(Mathf.Max(0, axial));
                float cross = (x - cx) * (x - cx) / Mathf.Pow(cx * .88f * taper,
                    2) + (y - centerY) * (y - centerY) / Mathf.Pow(radius * taper, 2);
                bool hull = cross <= 1;
                bool tower = Mathf.Abs(u) < .33f && y > centerY && z > d.z * .42f && z < d.z * .6f;
                bool fins = z > d.z - 6 && (Mathf.Abs(x - cx) < 1.2f || Mathf.Abs(y - centerY) < 1.2f) && y < d.y * .78f;
                bool skids = y < d.y * .22f && Mathf.Abs(Mathf.Abs(x - cx) - cx * .48f) < 1.2f && z > d.z * .2f && z < d.z * .8f;
                colour = (byte)(tower && y > d.y - 5 ? 2 : hull && y > centerY - 2 && y < centerY + 3
                    && z % 10 < 4 ? 2 : z < 3 || z > d.z - 5 ? 1 : 0);
                return hull || tower || fins || skids;
            }

            return false;
        }
    }
}
